def calculate_pendulum_oscillation(angle: Union[int, float], angle_unit: str = 'degree') -> Union[float, complex]:
    # Check if the angle unit is valid
    if angle_unit not in ['radian', 'degree']:
        raise ValueError("angle_unit must be either 'radian' or 'degree'")

    # Convert angle to radians if the unit is degrees
    if angle_unit == 'degree':
        angle_in_radians = angle * (math.pi / 180)
    else:
        angle_in_radians = angle

    # Calculate cosine
    if abs(angle_in_radians) > 1 or abs(angle_in_radians) < -1:
        # Return complex number with real part in therange and imaginary part for the exceeded part
        real_part = math.cos(angle_in_radians)
        imag_part = math.sqrt(1 - real_part**2)
        return complex(real_part, imag_part)
    else:
        return math.cos(angle_in_radians)
```

